            ​ 手腕处的绳结还好，虽然欧式紧缚下双手向背后高吊的动作很是痛苦，但起码绳结就在手腕周围不远，璃落很快便将它解开，但脚掌处连接的绳结就比较难了。璃落的双手本就在背后并拢紧缚，必须将自己缩成一团，维持着极限驷马的姿势才能堪堪够到另一道铁轨，可那个女孩又把绳结系在了璃落手指刚好能碰到的地方，璃落努力了几次，虽然成功找到了绳结的位置，却始终差一点才能夹住那根绳索。
            
            ​ 时间一分一秒地过去，璃落心里愈发焦急起来，可越是紧张反而越是容易出错，后来几次璃落的手指连绳结都碰不到了。
            
            ​ “呜呜呜！！”要死了吗？我要死了吗？心中的恐惧感越来越强。
            
            ​ 不管璃落再喜欢紧缚，也不希望自己的生命在这里结束……哪怕是在游戏过程中被主人失误虐待致死也要比现在在火车的碾压下痛苦地死去，连全尸也无法留下要好。
            
            ​ 突然，璃落的视线中出现一丝亮光，那是火车的的车头。
            
            ​ 呜……哐当哐当！
            
            ​ ……
            
            ​ “呼……呼……唔……”璃落趴在地面上，大口地喘着气，尽管身上被灌木和碎石割出无数大大小小的伤口，尽管仍然带着满身的紧缚动弹不得，但至少是活下来了……
            
            ​ 火车经过的那一瞬间，璃落成功地脱离了铁轨，顺着一侧斜坡翻滚了下去。
            
