            ​ 那是夜里经过此地的货车。
            
            ​ 突然的颠簸让一直在打瞌睡的司机清醒了过来，他看了看前面的路，发现没有什么状况后，赶紧揉了揉眼睛，心有余悸地继续向前行驶……
