            ​ “啊——”睡梦中的璃落突然惨叫一声惊醒过来，睁开眼，看到一脸幽怨地盯着自己的对床，璃落松了一口气，逃不掉的紧缚，快速靠近的火车，这些梦中恐怖的情节逐渐消逝，让璃落的心情逐渐平稳下来。
    
