            ​ 好久之后，终于跑累了停下来的璃落才发现一件尴尬的事情……刚刚只顾闷头向前冲，连方向都不管，这下她在这片工地中迷路了……
            
            ​ 心中已有猜测，冷静下来的璃落顾不得自己怕黑怕鬼，关掉了手电，尽量不发出声音，小心翼翼地开始寻找起出口。这里虽然还未完工，但是大部分的建筑和大门都已经建立起来，再加上道路上随处堆放的建材，天黑又看不清楚，璃落虽然能根据光亮找到大概方向，却始终找不到出口。
            
