            ​ 璃落靠坐在坑底，看着哗啦啦往下盖的泥土，嘲讽道：“那你现在是不是后悔了？被自己亲手挑选的女人葬送。”
            
            ​ 填土的速度慢了些，璃落抬起头，与这个居高临下看着自己的男人对视着，这还是她第一次直视那对阴翳的眼睛，毕竟在这之前，他还是她的主人。
            
            ​ 能决定生死还有生不如死的那种。
            
            ​ “啧啧，还以为你会比你姐姐聪明一点的，能被你找到的证据，早就变成废纸了。”
            
            ​ 璃落没有回答，如果不是有了决定性的证据，她怎么可能这么快暴露，不过这些还不能说出来。
            
            ​ “快到时间了，你的那些同事们也该来了吧，这么大的一座山，大概够他们找好几天了吧，不过那时候你也看不见了。”
            
            ​ 她的确看不到了，因为最后一大片土盖下来了，眼前只剩一片黑暗，伴随着窒息。
            
            ​ ……
            
            ​ ……
            
            ​ 上方的泥土被一层层掀开，璃落仿佛从梦中惊醒般突然睁开眼，眼前是熟悉的女孩。
            
            ​ “呼……”璃落深深松了口气，不同于之前短时间内的折磨，这几次梦境全都是以年为单位的长期压迫，几乎真实的经历让璃落难以从梦境中觉醒，不过总算是过去了。在最后即将失去意识时，璃落突然意识到梦中的姐姐与自己记忆中的姐姐差别很大，终于成功清醒过来。
            
            ​ “这次该结束了吧。”璃落挣扎了一下，束缚和土壤压制下依然动弹不得，只好疲惫地说道。
            
            ​ “嗯。”女孩点了点头，“你已经通过了考验。”
