            “你确定她最后自己跳楼了？然后就从窗外直接消失了？”安全局内，某个治安员小姐姐用笔支着下巴，表情有些精彩。
            
            “我确定！我是马上跟过去看的。”璃落说话间仍然有些激动，连带着手铐与审讯桌碰撞发出叮当叮当的声音。
            
            两个小时前，宋莹听璃落说了自己被绑架的事情后，赶紧带着璃落来到这里报案。接待她们的治安员小姐姐名叫安夕羽，璃落也认识，毕竟根据璃落回忆，这已经是她这个月第四次来这里了，前几次分别是因为被醉酒痴女捆绑调戏、路遇劫匪被抢后绑在路边以及镣铐自缚解不开来这里求救……
            
            璃落对报案的流程已经无比熟悉，熟练地登记信息、说明原因，最后再录个笔录就可以了。录笔录前，璃落例行问道：“这次可以试试审讯椅吗？”
            
            因为之前已经被拒绝过几次，璃落也只是看玩笑般地询问，没想到这一次安夕羽却答应了下来：“正好局里新配了一种升级版审讯椅需要找人尝试一下，我们几个人又没人愿意。不过提前说好，那东西肯定不太舒服哦。”
            
            “诶？那太好啦！璃落早就想试试了！”
            
            最新款式的审讯椅是桌椅一体型的，延续了旧版审讯椅的前倾靠背和固定栅栏，并且在椅子前方加上了一个可开合的金属小桌。桌子上方安放有手铐和指铐，下面则连接着金属脚铐脚笼。审讯椅的大部分位置都能调整松紧，方便将犯人拘束严密。
            
            璃落坐在椅子上后，明显感觉硬质的凳子有些硌屁股，而且稍微前倾的靠背也让她的腰部处于持续紧绷的姿势，可能坐不了多久就会腰酸背痛……这种专门为折磨犯人准备的拘束果然难受，不过璃落已经答应了小姐姐要帮忙试验，自然不好反悔。
            
            椅子下方有专门放置双脚的踏板，璃落在安夕羽的指示下脱下鞋袜，光着脚丫踩在踏板上，任由对方用上面附带的趾铐将她的每个脚趾都与踏板固定在一起。随后安夕羽将审讯桌合拢，桌下的半圆状脚铐便与踏板上方的另一半脚铐牢牢合拢，将璃落的双脚彻底固定在审讯桌之中。
            
            同时，随着审讯桌闭合，桌子上方的栏杆也贴紧着璃落胸部下方与椅子两侧固定，将璃落的身体和大臂束缚在审讯椅上。
            
            然后用审讯桌上自带的手铐将璃落双手分别铐好，再将璃落双手放在桌子上手掌形状的凹槽中，同双脚一样将每个手指都铐在审讯桌上。最后，一个挂锁锁在靠背上一键解锁的铁环上，璃落便被完全拘束在这张审讯椅上。
            
            “呼……终于绑好了。试试看感觉怎么样？”
            
            “这些束具都铐得好紧诶！身子完全动不了！”试着动了动，除了脑袋，整个身子都被审讯椅牢牢固定着，钢铁塑造的铐环带来无与伦比绝望感，显然如果没有钥匙开锁，任何人都不可能帮助她从这金属笼中逃脱。“不过感觉夕羽姐操作起来很繁琐的样子诶，每个犯人都要这样花好久的时间来拘束吗？”
            
            “正经审问的时候当然不用全铐上，大部分囚犯戴个手铐就足够了，这次还不是要让你测试审讯椅功能嘛。”
            
            “哇！这么说璃落这一身拘束比囚犯都严格呀，这也算特级监禁了吧！”
            
            “噗……你还骄傲上了，想体验监禁去找监狱体验店，那里面五花八门的拘束具可多了，咱们这正经地方可不是给你玩的，也就这次赶上测试让你帮帮忙！”安夕羽又擦了擦汗，坐在璃落对面的椅子上，“好了，拘束也满足了，赶紧开始录笔录吧。”
            
            “嘿嘿嘿……好哦！正好璃落也坐得有些屁股疼了。”
            
            十几分钟后，安夕羽合上手中的记录本，“好，那么就先这样，你……”
            
            “我回去等夕羽姐的消息就好啦！”璃落抢先答道。
            
            “可以呀，都会抢答了。”安夕羽摸了摸璃落的脑袋，拿出钥匙准备把她从审讯椅中放出来，“你这运气也是没谁了，天天都能遇到案子，来这里都快比回家频繁了吧。”
            
            “咱也不想呀……”璃落吐槽着，稍稍扭了扭还能勉强动弹的屁股。审讯椅不愧是给犯人准备的，刚刚被固定上来不到半小时，反人体力学的椅子就已经让她腰酸背痛屁股疼，完全没有拘束起来动不了的享受，只剩下折磨，好在终于可以解脱啦……
            
            就这样，璃落听着后面安夕羽开锁的声音，时不时稍微换个姿势让自己更加好受一些……直到十分钟后，开锁的动静还没停下来。
            
            “夕羽姐？”
            
            “嘶……这破锁好像坏了……璃落你再忍一下，我去联系隔壁管工程的来帮忙！”
            
            “啊？！”
