            晚饭时间，璃落坐在餐馆柔软的靠椅上，一手捂着肚子一手捶着后腰，“咕……好饿……腰好疼……今天真是太倒霉了！”
    
            “噗！都一天没吃饭了，肯定饿呀！”宋莹看到璃落的样子忍不住莞尔，“你这运气也是没谁了，人家制式的审讯椅，出问题的概率小于百分之一，也被你遇到了。”
            
