            ​ 几天之后，璃落又来到了灰风的紧缚素材店铺。

            ​ “呦小璃落又来啦，上次的那只大虫子怎么样？”

            ​ “还不错。”说道这个璃落的脸就有些奇怪的红润，“就是……就是有几个地方感觉还可以再改改呢。璃落想要一只自己的专属大虫子。”

            ​ “哦？那璃落能给什么报酬呢？”

            ​ “给你两只笨璃璃帮忙去深渊之森探索！”璃落举起三根手指。

            ​ “噗！第三只是你自己吗？”

            ​ “诶诶？！可不可以嘛！”

            ​ “嗯……也不是不可以，不过小璃落要答应我以后经常来哦，这里可有不少魔物需要小萝莉来实验效果呢。”

            ​ “我答应你啦！”

            ​ ……

            ​ 三天后，璃落如愿以偿地将一只深绿色的巨大毛毛虫带回了自己的小窝。为了安置这只足足有三米长一米宽的大肉虫，璃落还特地让璃雪姐姐帮忙给自己的卧室旁开辟了一处折叠空间。

            ​ 很快就到了晚上，到了需要用到这只睡袋虫虫的时候，璃落一蹦一跳地回到房间——灰风说这次大虫子已经不会再消化掉其他拘束具了，璃落特地让沐沐把自己绑得紧紧的之后才回来。

            ​ 捆绑方式还是差不多，双手被极限后手观音缚在背后，从手腕到手肘全部被粉色棉绳重重捆紧，两只小手则握着棉球被胶带包裹成团。下身就是从大腿到脚踝的圈圈缠绕啦，因为璃落还要自己跳到房间，而且听说大虫子自带按摩脚脚服务，沐沐就没有给璃落的脚丫再增加束缚，留下唯一自由的白丝雪糕。

            ​ 房间内，大虫子已经在璃落的示意下张开大嘴，和花瓣很像的大嘴向四周张开，露出里面红粉色的柔软内壁。

            ​ “啪叽！”璃落很快便跳入虫子的口内，随着大虫子的蠕动体会着越来越深的紧缚感。

