            ​ “绳子，胶带，丝袜……清单上的东西都买齐了，可以回领地了。”这天，在外采购了一上午的晓语总算提着几个大口袋回到了领地。

            ​ 把采购的东西放到仓库里，回家的路上晓语正好路过了前一段时间自己刚刚建立的晓语大酒店。

            ​ “不知道最近酒店的生意怎么样。”这样想着，晓语走进了酒店中，前台负责接待的璃果（某只笨璃璃的名字）看到老板，赶紧上前迎接。

            ​ “晓语老板今天过来视察吗？要不要给您倒杯饮料去呀。”

            ​ “来一杯水就好。”刚刚采购完，晓语也有些口渴，一边接过服务人员的水，一边询问起近期酒店的状况。

            ​ ……

            ​ “之前说的那个活动你们安排就好，我就先回去了，你们加油，有什么问题可以随时找我反应哦。”

            ​ “好，晓语老板慢走……”璃果对着逐渐走远的晓语挥了挥手，然后轻声嘟囔道，“差不多该起效果了吧。”

            ​ 噗通……

            ​ 话音刚落，走出酒店的晓语栽倒在了地上。

            ​ ……

            ​ “呜呜呜？（这是怎么了？）”不久，再一次恢复意识的晓语缓缓睁开眼睛，首先映入眼前的就是眼前的一个牌子，上面写着：今日店主生日，亲自下场做吉祥物，并且推出了咸鱼大乐透活动哦，每次只需要，欢淫大家前来试玩哦，每次只要10咸鱼币……

            ​ “呜呜呜！？（我什么时候成了吉祥物了！？）”晓语被牌子上的字雷得不轻，下意识地想要挣扎，然而不出所料，手脚都被紧紧地捆在了背后，形成一个极限的驷马姿势无法动弹。

            ​ 此时璃果走到了晓语面前，抚摸了一下她被四道绳索重重缠绕捆紧的白丝小腿，轻声说道，“老板，生日就不要太累啦，酒店的大家专门准备了这个礼物哦，正好你也可以好好休息一下呢。”

            ​ “呜呜呜！（这样怎么能算休息！你这只笨璃又是跟哪里学坏了！）”晓语被这一套说辞气得够呛，再一次挣扎起来，然而五花大绑的双手，并拢后抬的白丝脚丫全都早已失去了移动能力，最多只能在原地不断打转罢了。

            ​ 正在晓语不断挣扎时，某只在领地闲逛的流浪者率先发现了她。10枚咸鱼币投下去，旁边的箱子中掉落出了一只震动棒……

            ​ “呜呜呜！！呜呜呜呜……呜呜……”后来，据晓语本人透露，这个生日她还是过得很“快乐”的，而且第二天璃果也受到了晓语的款待，同样“狠快乐”地度过了一整天……
