            ​ 又是平静的一天，结束了一天的工作，糯米和团子一起依偎在沙发上看着新出的网剧，正巧剧中女主角被仇家报复绑架，糯米的眼神明显亮了起来。

            ​ 然而，镜头一转，看到女主手上只有松松垮垮的两圈绳子后，糯米顿时失去了性质……

