            ​ “诶诶？这么早？”看着急匆匆离去的团子，糯米揉着大腿疑惑地自言自语，“我刚刚有说要试试什么吗？”

            ​ ……

            ​ “现在的电视剧真是的，绑人这么敷衍就不要写这种情节嘛！”回到了自己的房间，团子一边低声抱怨着，一边从床底隔层取出一个袋子，里面赫然装着几捆整齐的麻绳……显然团子被刚刚的情节勾起了性质，电视剧中见不到像样的捆绑，那就只好自己亲身体会了……

