            ​ 横着五圈，竖着三圈，再收紧打结，继续往上……脚踝，小腿，膝盖，大腿这些关键部位很快便被绳索逐一攻占，让团子白嫩的双腿强行合拢为一个整体。

            ​ 闭上眼，感受着绳索对双足的禁锢，团子沉迷地将双手背后，幻想自己就是剧中被绑架的女主……然而毫无拘束的双臂却总让她感觉怪怪的，明明自己是可以随时解开束缚的……

            ​ “呜……”感觉全没了，团子不得不坐起身来，打开私藏的小书《萌新日式自缚教程》，继续攻坚一学就废的自缚教程……

            ​ 半个小时后……

            ​ “呜呜呜呜！！！”团子抓狂中……

            ​ 又过了十分钟，被剧情勾起的兴趣慢慢平息，自缚双手仍然没有头绪的团子正准备放弃，却突然听到糯米的敲门声……

            ​ “团子，你手机在外面响了，我给你送进来吗？”

