            ​ “这是刚刚研究出来的新产品，虽然它能实时维持身体需要的营养，但是不到时间它也是绝对解不开的，所以你要是尝试的话，一定要记得在安全的地方使用哈。对了，用完了记得反馈，看看它效果怎么样。”

            ​ 以上是在拿到这根自动束缚绳索时咸鱼的嘱咐，为了这为数不多的测试资格，清雨可足足在咸鱼那里念叨了好几天，不过结果是好的，心心念念的自缚神器终于拿到手了。

            ​ 据说这根绳子是为了长期拘束准备的，最多甚至可以捆绑几个月不松开，清雨自然也要提前做好准备。首先自然要把身体里里外外都清理干净，全身涂抹好防止长时间不运动导致肌肉退化的药剂，然后再穿上漂亮的浅绿色连衣裙，赤着双脚扑倒在床上。

            ​ “嗯……设置多长时间好呢……不管了随机吧，反正最少也要一周……”随便按了几个数字，清雨将遥控器打开，然后随手一扔，便自觉地将双臂并拢在背后等待束缚了……

            ​ 咸鱼出品必属精品，自动拘束绳索也没有辜负清雨的期待，原本小小的一团伸展后足足有将近百米长，灵巧的绳头穿过清雨手臂，将她的手腕相对捆缚起来，又拉拽着手臂反折向上同肩膀绳索相连，捆成后手观音的形状。

            ​ 剩余的长长绳索则继续向下，将清雨的手肘同样并拢捆缚起来，形成更加极限的紧缚姿势，又顺着腋下穿梭加固着大臂，直到将清雨上身捆到动也不能动，手臂牢牢禁锢在背后，就连手指都被后续的绳索逐一加固，真正做到了一根手指都动弹不得。

            ​ 虽然双手已经失去作用，绳索却仍没有完成任务，继续在清雨胸前穿插着，为她缚上严密又漂亮的绳衣，最终在胯下汇聚成几颗硕大的绳结，牢牢压入女孩子的敏感部位……

