            ​ 半个小时后，天天挽着蔫哒哒的小寒枝，从侧门溜进了影院……

            ​ 电影早已开始播放，她们已经错过了开头，不过寒枝却没有精力去管电影里面讲了啥。因为！天天！那个！变态！在刚刚折腾完她后还不忘把跳蛋贴在她的敏感地带，而且竟然持续开着低档位！

            ​ 虽然持续刺激下寒枝现在已经没有那么敏感，但跳蛋的折磨始终没有办法忽视，她甚至感觉自己做着的椅子都开始跟着震动起来了……

            ​ 身边的一个女孩已经忍不住侧头像她看过来，寒枝终于忍受不住，用手机给天天打了一行“我要去个厕所”，就丢下她赶紧跑了出去。

            ​ “呼……”取出折腾她一路的跳蛋，摘下口罩取出嘴里塞得满满的棉袜，寒枝终于松了一口气，这一路上也太刺激了，她到现在腿还是软的。

            ​ 实在不想再次面对天天的调教了，寒枝干脆自己悄悄溜出影院，打了个车先回了家……

            ​ 当然，放大姐姐鸽子的代价是很严重的，当天晚上，小寒枝又被大姐姐绑在了床上，五花并腿驷马，口球鼻钩耳塞，还要一边忍受着大姐姐的玩弄，一边被迫带着VR眼睛观看小电影。美名其曰补回来下午没看完的电影。

