            ...new TextTitleBase('酒店绑架工作'), 
            roles: ['孤月', '晓语'],
            author: '孤月',
            content: `
            在一天的深夜，孤月悄咪咪的溜进了晓语酒店，躲在了柜台后面。
            突然，一阵脚步声传了过来。”这帮客人！一个个的都在那说咱好可爱……我……我才不会高兴呢！“躲在柜台后面的孤月突然听到了这么一段话：”这么明显的傲娇啊……“孤月无奈的吐槽，等到脚步声越来越近的时候，孤月突然跳出来，从空间里拿出一把小刀抵在了晓语的脖子上：”别动！“孤月低声呵斥道”就是你之前报的警吧“晓语愣了愣，随后反应过来：“是你？那个把我打晕的……”孤月发现对方认出自己之后笑了笑：“认出来咱了？要不是你咱任务也不会失败……也不会拿不到钱……”孤月一边碎碎念一边往自己的裙下摸，摸出了一捆绳子和一卷胶带”你……嘶……“晓语看到之后脸色突然一变，似乎是想到了什么“喂喂喂……咱可没那些什么奇奇怪怪的想法，再说了，美少女不都是应该有四次元裙底的吗？”孤月笑了笑，掩盖住了其实是悄咪咪的从自己的空间里面拿出来的，随后绕到晓语的背后开始了捆绑。
            孤月先把晓语的双手背到身后，让对方双手握住自己的手肘，随后用胶带一圈一圈的缠，直到整个小臂都被胶带覆盖，从外面看起来似乎本来就是一体的时候才停下来，随后拿出绳子，在晓语的胸部上下捆了几道，把大臂和身体固定到一起。“哼……不解气……”随即孤月蹲了下来，把手摸进晓语的裙下，开始脱晓语的小内内。
            正在此时，晓语感觉到这似乎是一个很好的逃跑机会，把腿往后一蹬，随即整个人往前跑“只要跑出酒店到了大街上……这个变态就会再次被抓获了！”晓语正在思考着逃离后的行动，却突然脚下一滑，摔倒了。原来是孤月被踹倒了之后发现晓语在逃跑后，从空间里找出一瓶水，扔到晓语前面，结果晓语踩到之后滑倒了。
            “行啊你……还踹我？嘶……”孤月揉了揉自己的钢板，气愤的坐在晓语身上，强制性的把小内内扒下来之后揉成一团，凑到了晓语的嘴边。晓语知道这是要做什么，于是死活都不张嘴，孤月想了想，随后捏住了晓语的鼻子。过了一段时间后，晓语终于忍不住了”哈……哈……哈……呜！！！“趁着晓语还在大喘气的时候孤月趁机一把把布团塞了进去”哼，让你尝尝自己的味道吧“孤月一边塞一边恶狠狠的说着，随后外面还贴了层胶布让晓语吐不出来”呜呜……“晓语拼命的用舌头往外推嘴里的布团，但是没法推出去。”味道……好奇怪啊……不要……“晓语一边挣扎，一边想着。
            孤月随即把晓语脚上的鞋袜扒掉，捆成开腿缚的样子。随即又从自己的裙下摸出一个小玩具，上面似乎还沾着水迹”呜呜！呜呜！！！“晓语一看到这个便开始疯狂的挣扎，并且头摇的像个拨浪鼓一样。”哼哼你说不行就不行？那你把我放哪去了“随即把小玩具放到晓语的裙下，打开低档后把遥控器用胶带捆到晓语的大腿上”哼哼咱享受过的感觉怎么样？“孤月在一旁坏坏的说道，而内心想的其实是”其实只是用一些奇奇怪怪的液体泡过的啦……还没人用过啦……“
            随后孤月没再管在地上挣扎的晓语，走出了晓语酒店，随后再进来的时候拖着一个大行李箱，足够把晓语放进去的那种”哼哼虽然你长得比咱高，熊熊比咱大，挣得钱比咱多……”孤月越说自己感觉越难受，急忙转移了话题。“但是你还是被咱抓住了不是吗？而且……你个混蛋阻止咱挣钱了！”孤月一想到这个就非常生气，随即把大行李箱打开，把晓语扔进去后说道：“哼……一会再来看你”于是不管晓语羞红的面色关上了行李箱的盖子，拖出晓语酒店。“好沉啊……吃太多了？”孤月气喘吁吁的把大行李箱放进自己车的后备箱，关上后备箱盖，随即向着领地外开去。
            车在一个巨大的池子旁边停了下来，随即孤月把行李箱拖了下来，拉到池子旁边后打开，里面的晓语早已经脸色红润，下面也已经湿透“这样才对嘛”孤月笑了笑，随后把晓语嘴上的胶带撕下来，把小内内拿出来“咳咳咳……你到底要干什么……”晓语咳嗽了两声后急忙说道“欸别急别急，咱先交换下名字吗毕竟下一次见面……可就不知道多久了”孤月不紧不慢的说道。“哼，我才不会跟你说呢！你个绑架——呜呜！”话还没说完，孤月又从裙下摸出了一个开口器塞到晓语嘴里，把皮带扣死，随即又给晓语带上了眼罩，把小玩具拿了下来，随即凑到晓语的耳边说道：“你知道这里是哪里吗？这里可是一个触手池我上次来的时候差点没被它们拖下去，估计是饿了吧……你觉得碰到你这个没有反抗能力的食物他们会怎么做呢？”晓语听到这番话之后开始疯狂的挣扎，想要挣开身上的束缚。“对了，咱叫孤月。再见咯，不知道名姓的老板娘。下次再见……可就不知道啥时候了哦”话音刚落，孤月就把耳塞给晓语带上了，随即把晓语拉到触手池边，随即快速的跑回车里。
            没过多久，就有一堆触手把还在池边挣扎的晓语带了进去，孤月随即开车离开了。
            在漆黑的午夜里，没有人会知道晓语到底去了哪里，而她什么时候会被发现呢？可能要等到领地扩建的时候了吧……
            `
