            ​ 入眼所见是两个梳着双丫髻的女孩，端着盘子，上面放着衣物。后面还有两位嬷嬷走上前驾起惠惠，方便一旁的丫鬟把一件桃红色的袍子给惠惠穿上，另一边的丫鬟则拿出红绳熟练向着惠惠双臂缠绕，又将绳子汇拢到身后捆住惠惠的双臂，多余的绳索还在惠惠的胸部上下缠绕着，将惠惠的胸前小馒头挤得胀胀的。

