                （璃落）
                春季的午后十分，温暖的阳光洒在街道上，路旁摆摊的小姐姐慵懒地眯着眼，欣赏着街对面两个正在散步的漂亮姑娘。其中，那位缩在宽大风衣中的女孩似乎身体不太舒服，一直蜷缩着身体小步行走，有时还会突然全身颤抖。好在这种时候她身旁看起来成熟一些的女孩便会停下来，温柔的抱住她，直到对方恢复才会带着她接着往前走。
