                “呜？！呜呜？”璃落惊讶地扭头望向玖儿，即使她被口罩遮住了大半张脸，也能明显看出此时她无比震惊的表情……哪有这么坑妹的啊！
                然而璃落此时没有能力也没有精力去吐槽玖儿了，因为紧勒在她下体的股绳又开始孜孜不倦地震动起来，伴随着高跟鞋刺激下的挠痒。璃落赶紧原地蹲下忍住不出声，可这次因为是玖儿手动操控的，刚刚的经验已然不适用。璃落忍耐了好久，刺激依然没有停下，还因为之前几次的快感积累显得愈发强烈，感觉自己马上就要在这光天化日之下流水了，璃落顾不得脚下的刺激，猛然起身扑到了玖儿怀中。
                “诶？怎么了怎么了妹妹？”看到璃落主动扑向自己，玖儿受宠若惊，温柔的摸了摸头，不过很快她就发现妹妹的身体在不停颤抖，似乎在忍耐着什么，又看到妹妹的脸蛋已经几乎红成了苹果，玖儿终于后知后觉地反应了过来，“啊，是震动调太高了吗？等下哦，姐姐这就关掉！”
