        　　  她的手上又被戴上了类似真丝手套的东西，但是非常非常的紧，让她感觉自己的手就像是迟钝了许多。然后一根根的手指被蜷缩起来，握成拳头，戴上了手笼，手笼包裹了整个手部，就像是一个真正的握紧的拳头，紧致到几乎让洛洛感觉不到自己的手指了，然后被拉着，紧紧的贴着自己的肩膀，没有一丝一毫的空隙。
        　　
