        　　璃落非常不想在晚上品尝舍友穿了一天的臭袜子，但为了自己的成绩，咬咬牙，继续读了下去。

        　　再又被清涵和晓星折磨了一下午后，璃落又成功被拿下五分，一共被扣除了七分！

