        　　“唔，按照规则，第一分的惩罚——你应该把我穿过的袜子含在嘴里整整一晚上……”说着，丹秋蹬下跑步鞋，露出了一双白袜小脚——因为运动的关系，汗液充分浸透了脚底，导致整个袜底，尤其是脚趾缝的位置有些发黄，一股汗味和少女的体香在空气中弥漫开来。

