        　　璃落的嘴巴确实娇小，一双白棉袜将她的嘴巴堵得毫无破绽，严丝合缝地占据了她口腔里的每一丝空间。就这样，一双在丹秋脚下陪着她运动了一天的棉袜被堵进了璃落的小嘴中，附着的汗液和皮屑随着袜底一同压在璃落的舌头上，由口水湿润后吞咽入腹——到这里，刚刚开始的惩罚已经让璃落脸红的跟一个红苹果一样，脑袋上仿佛都能看见蒸腾的烟雾。

