        　　除了璃落，大家都睡得很舒服。璃落此时像一个茧一般，厚厚的几层丝袜已经完全无法从外界看到璃落的表情——当然璃落也无法观察到外界的情况，里面的弹力绳捆绑仍然没有丝毫松懈，双手更是紧握着粗糙的运动袜，一刻也无法分离。捆绑在嘴里和鼻前的长短棉袜更是严重的折磨——虽然已经从丹秋和晓星脚上取下了好几个小时，气味也没有什么消散，嘴里的棉袜反而因为吸收了自己的口水膨胀的更大，将本就填满的口腔更是撑的鼓鼓的……就这样，少女在这般特殊的补习惩罚下，也沉沉进入了梦乡。

