        多多将晓语放到地上，可以清晰地看到，晓语的手臂被闪着蓝色光芒的绳索横向并拢着牢牢捆在背后，多余的绳索还紧紧勒着她初具规模的欧派，将她的身体同大臂一同束缚起来，上身仅剩下的能活动的小手也被蓝色凝胶握拳包裹。多多还好奇地用手指戳了戳，包裹手指的凝胶软软的，但显然不是轻易能去除的。

        除此之外，晓语的黑丝双腿也被同样的绳索并拢捆缚，从大腿到脚掌每隔几寸便有绳圈缠绕，密密麻麻的绳索几乎将她的双腿完全包裹。而且脚掌的绳索还与手臂的相连，收紧到极致的绳索让晓语的身体弯成极限的弓形，显然即使她醒来也很难做出什么有效的挣扎。 

        同时，晓语的眼睛被眼罩覆盖，她的小嘴也被透明胶带封的死死的，从嘴巴被迫张开大的缝隙中还可以看到里面塞满了的白色棉袜。

        多多稍微松了松晓语身上的驷马链接绳，虽然没有完全解救她手脚被迫相连的姿势，也能让她不那么难受，至于身上其他的拘束嘛……反正还需要她在这里多待几天，就省的解开啦。随后多多将晓语抱到拘束台，用附带的拘束带将她禁锢在台上，然后给她安置好强高模式的震动棒以及妹汁储存管道。

        “不知道这位小姐姐能不能开发出新品种的原料呀。”处理好晓语，多多说着走出了地牢。随着她转身离去，晓语的身体似乎小幅度的挣扎了一下，不知是因为被榨汁的自然反应还是已经苏醒，反正也没有区别，她都是一样的完全动弹不得，直到多多来解救她之前……
