            ​ 学习的过程总是缓慢的，不过破晓满心都是自己给自己制作新年礼物的新奇感，倒也不会无聊。很快，清雨的上半身就被破晓五花大绑了起来，两只手手也被强行握拳后用胶带缠绕了不知道多少圈。
            
