            ​ “花音在吗？”匆忙回到自己的小屋中，破晓探头呼叫自己的舍友。
    
            ​ “破晓干什么鸭……哎呀，这是谁？！”花音刚刚洗完澡，刚好披着浴巾出来，猛然间见到破晓拽着被捆成球球的清雨走进门，吓得她一下子没抓住浴巾……春光乍泄，花音赶紧捡起浴巾遮住身前柔软，继而好奇地问道。
            
            ​ “这是咱在领地的一个朋友，今天好不容易把她捆回来啦，正好来给咱做新年礼物！”
            
