            ​ “嗯嗯，我试一试……”
            
            ​ 花音与破晓这两小只都是m，与破晓相比花音更是自缚都很少，玩绳子什么的对她们来说有点困难，好在这次破晓准备的是全套拘束皮具，要比绳索好操作的多。
            
            ​ 这是破晓珍藏的一整套狗狗拘束服，用于拘束四肢的皮带密密麻麻，两人花了好大功夫才整理明白……这自然也是破晓给自己准备的礼物之一了——她想被捆成狗狗的样子，然后推着之前捆好的清雨球玩！
            
            ​ 破晓自觉地将手脚折叠起来，双手扶着肩膀，跪坐在软垫上，配合着花音将一条条皮带拘束好，心情也愈发激动起来……
            
            ​ 不一会……
            
