            ​ 比水瑶的打劫方法高级多了——因为随着一阵刹车声，下来几个黑衣女人直接把水瑶强行拐上了车……没有让水瑶有呼救的机会，因为一块沾了乙醚的方巾一只捂在口鼻上，直到确定她昏迷之后才放下来。
            
