            ​ 泉此方对束缚方面虽然兴趣浓厚，但手法不太熟练，只从教程中选了一个比较简单的欧式紧缚，将水瑶的双手在背后平行着捆了起来，在水瑶喵强大的柔韧性下，就连手肘也可以严丝合缝地束缚在一起。
            
