            今天是第一百天了，咕咕鸟这次穿着一件宽大的祭司长袍走来，这次咕咕鸟没有用奇怪鸟面具遮住自己的脸，不过咕咕鸟这张绝美的脸蛋上露出些许奇怪的表情，而且祭司袍袖子垂在两边空着，想来里面应该被绳子绑的紧紧的吧。
            咕咕鸟身后还跟着两个人，分别是黑色长发的璃雪推着一个白色的轮椅，再后面是扎着粉色马尾的璃落，不过璃落身上只穿着内衣，嘴里塞着一个大大的口球，而身子被密密麻麻的绳子绑着，而双手在背后反折双掌相对以极限背祷式绑着固定着。
            一根锁链连着璃落脖子上的项圈，锁链另外一头挂在璃雪的手上，璃落双脚在膝盖和脚腕都锁着一个粗大的锁铐，铐子之间有二十厘米长的锁链，脚上穿着一个十厘米长的高跟鞋，璃落就这么小步的跟在璃雪后面。
            咕咕鸟介绍说：“这位是领地的管理者璃雪大人，而后面那位是璃雪大人的妹妹璃落大人。”
            璃雪略微点头示意，璃落倒是呜呜几声回应。
            咕咕鸟又介绍说：“笼子里面的就是圣女大人了，而外面这位是圣女大人的贴身女仆姬灵大人。”
            姬灵也看了看两人，这四个人就这么站在笼子前面。
