            好在治安官也没有强求，确认夕噬离开时，北寻已经失去了意识后，便没有在这个让她羞耻的事情上多问。
    
            北寻才不想承认，后来她被下面的三个玩具折磨地欲仙欲死：附带软毛能震动的尿道塞、在小穴中疯狂旋转的棒棒、以及那个竟然带有电击功能的拉珠，这些原本都是北寻好奇但绝对不敢玩的收藏品，却在那天被夕噬在她身上试了个遍。
    
