                在吱呀吱呀声中木门被推开，戴黑边框眼镜，穿全身皮带的御姐牵着后边一个头上戴着狗狗头套，四肢折叠被包裹在宠物拘束衣里的人坐到空床上，皮靴高跟仿佛要把散发着霉味的木地板踩烂“哦？你好，我叫语嫣。”语嫣无视了兔姬，冲着惠惠寒暄起来。“那是你的M吗？”“啊……啊，是的，还是我的夫人。”“哦～很高兴认识你们。”语嫣推了推眼镜，然后踢了踢趴着的小腹，“喂，贱狗，给新朋友打个招呼。”人形犬呜咽了几声，努力的晃着屁股，后边深入后庭的尾巴也跟着摇晃起来。人形犬的嘴巴似乎被堵的严严实实，不仔细听根本听不出来。“语嫣小姐，您应该是熟客了吧？”“哦？是的，我带着我的狗狗来这里很多次了，你们是第一次来吗？”“是这样的。”“哦～难怪看起来不太自然，放心吧，这里虽然古怪，但温泉却有特别效果。”“哦？”“这里的温泉除了能洗去身上的疾病，还能放大人身上的属性，强势的人更加强势，顺从的人更加顺从。”“哇哦……”听到这里，惠惠目光不自觉的飘向兔姬，兔姬碍于外人在场只好装模作样的呻吟几声。
                不知不觉间，午夜钟声敲响，外面传来阵阵锣响，语嫣突然喊住惠惠，“这一波是老客户，我们现在去他们不会接待的。”“你不也是吗？”“我…顶多算个熟客，还不至于是老客户，对了，你们知道吗，很久以前，这里有另一个名字。”“什么？”“黄泉村。”从语嫣口中，惠惠了解到当年这里发生过的事，“那是40年前了，某一天晚上，一个全身漆黑的怪物出现在村子里，怪物没有五官，从身体里发出咕噜咕噜的声音，村民十分害怕，一个村民壮着胆子用棍子戳了戳怪物，不料怪物突然撕裂出血盆大口，一口将村民咬成两截！村民一拥而上，将怪物乱棍打死，丢在乱葬岗，从那之后，这里每年都会失踪新婚的夫妇，因此这里人丁渐渐稀少，剩下的人也搬离这里，为了根绝这场诅咒，走时人们纷纷在家中扎下自己的替身，然后一把火将整个村子烧光，在所有人走后，大地突然塌陷，温泉水漫了上来…”语嫣还想讲下去，一阵喇叭声响起，“哦？到时间了，我们快走吧。”
                旅馆的房间中走出许多人，有的和惠惠兔姬一样情侣结伴而来，有的独自前来，还有一些老人，慢悠悠的走在最后。人群中，兔姬好像还看见了之前叫多多的猫娘。
                通过漫长的甬道，惠惠来到了一个巨大的穹顶。温泉在池中以一种几乎沸腾的姿态翻滚。身穿蓝色燕尾服的假面绅士登上高台，“女士们先生们——我知道为了来这，各位付出了高昂的代价，但是，这是物有所值的——”说完转身点头，台下的人这才发现有一位满头白发的佝偻老太，在众人的不解中，老太没有一丝犹豫一跃而下。温泉仿佛感应到了什么，搅起一个巨大的漩涡。在场的人无不把头伸长，过了很久，池子逐渐平静下来。惨白的爪子伸出水面，接着一个18岁左右的年轻女性从水池里爬了出来。“我真的变年轻了！”
                人群蠢蠢欲动，这时假面绅士再次登上高台，“年轻的伴侣们，我们为你们准备了更劲爆惊喜！请随我来吧！”
                惠惠带着兔姬来到了一个独立的小山洞，里面有一个浅浅的小水塘，散发着温柔的热气。“等等。”兔姬叫住惠惠，“我感觉不对劲，整个地球就没有二级以上的文明，如此返老还童的奇迹究竟是怎么来的。”“你这么一说，好像也有道理…”兔姬打开门往外看了一眼，刚才人声鼎沸的大厅此时竟空无一人，诡异的气氛笼罩全场。确认无人后，兔姬悄悄出去。远处的洞房突然喷出大量白雾，接着，刚才的假面绅士带着跳入水池的白发少女从里面走出来，待两人进入下一间时兔姬偷偷趴在门缝偷窥，里面的情侣此时已经被冻成了两句冰雕。“可恶…怎么还有生命体征，果然有问题！”
                等两人从房间出来时，兔姬迎面拦住，“你们是什么人！低温催眠人类要干什么！”假面绅士并不惊讶，从容的变回真身：浑身棕褐色的皮肤，头部两个眼镜占据了整个脑袋，菊花一样的口器不停开合着。“我是土星人，你可以叫我布莱克——”“你们设计这一切的目的是什么！”“我们星球需要奴隶，因此，我会选中合适的地球人去为我们生育奴隶。”“这温泉又是怎么回事？！”“这是我们土星的科技，好了诺曼，杀了她。”说完头也不回的跑路。
                “吼！”白发少女冲破穹顶，变成巨大的狼头雪人身怪物，兔姬紧跟着变大，两人在山间盆地中展开战斗。兔姬使出燕式飞踢，雪怪侧身让过，兔姬在地上连续滚翻两下，半蹲在地上双手十字交叉，“天使激光射击！”光线在诺曼身上爆炸，发出痛苦的嚎叫。兔姬上前准备肉搏，诺曼突然将一只手搭在另一只手上喷射冷气，兔姬招架不住被驱赶到喷射范围之外，见攻击有效，诺曼一边喷射冷气的同时一边从口中喷射冷冻射线，兔姬连续后翻勉强拉开距离，在身前画出一个正方形光盾，抵御韩流袭击。诺曼的寒流一时无法突破。兔姬双臂合十，指尖发射出两道射线照射诺曼头和下肢，接着双臂打开上移，将诺曼带到了天上，随后使用集束射线将诺曼炸成碎片，山中升起的布莱克飞船也被兔姬使用手里剑光线炸毁。“别得意！你们谁都别想活！啊——”
                盆地里突然爆炸迭起，晃动的地面一度使兔姬失去平衡。火光冲天的同时，地下温泉也漫了上来。“神奇的兔姬喷雾！”奇妙的星星闪烁着，兔姬喷雾顷刻之间熄灭大火，接着兔姬手臂在胸前交叉，漫上来的水突然停止上升，转而降回地下，地面也随之上升。
                “惠惠——”“没事——我在这——”惠惠站在石头上冲兔姬招手，“好消息，那些被抓起来的人全部都被救出来了，我好像看见了璃落也在里面。”“这么说来，那封信的确是被绑架后写出的了。”兔姬点点头。“那个…兔子啊…”“嗯？”惠惠扭捏起来“你那样…真的很涩…”“！”兔姬的脸一下全红，然后踢了惠惠屁股一脚。
