            　　“两位贵宾，你们可以在这间小屋里换适合泡温泉的衣服，本店在里面提供了上千种款式和颜色供贵宾们挑选。放心，那个裂缝是专门设计过的，在外面是看不全里面的情况的。”小萌一边介绍假山上盆景的做工与设计，一边带着璃落和流萤来到温泉边。“嗯，最多，可以为你们增加些许的情趣。”小萌快速扫了一眼璃落和流萤，用一副我懂的的表情说道。“我们不是那种关系啦。”流萤的俏脸通红，再次作出双臂举至胸前双手攥拳的经典姿势。小萌恢复了职业微笑，岔开话题：“当然了，不换衣服也可以泡温泉哦，小屋里有最新的烘干装置，保证不会损伤您的肌肤和任何衣物。”“理解，为了过审嘛。”璃落选择的回答选项依旧跳脱。小萌有些适应璃落的说话方式了，表情没有变化：“二位如果准备好泡温泉了，可以来温泉这里的平台找我。”说完，小萌来到温泉边，旁若无人地脱掉了身上的女仆装，并慢条斯理地脱下了丝袜和高跟鞋，只穿着黑色蕾丝内衣内裤，光脚来到温泉里的平台上，优雅地坐在躺椅上等待流萤和璃落。
            　　
            　　“不许偷看哦。”流萤看了一眼璃落，一脸娇羞地走进了小屋。“她是在期待我看吗？”璃落没有思考太久，身体诚实地走近了小屋，自然地扒在缝隙处向屋内看。但屋内的景色让璃落略有些失望，小萌确实没有说谎，屋内的光影斑驳，流萤换衣服时隐私的部位自带一层圣光马赛克，能完全看清的只有藕臂皓腕葱指玉足，偶尔能瞥见若隐若现的纤细小腿。“她真好看。”璃落由衷感慨道。
            　　
            　　很快，流萤换好了底色绿色白色花纹的内衣内裤，而璃落也随后进入小屋挑选了黑白花纹的内衣内裤换上。
            　　
            　　“两位的身材真不错呢。”小萌站起身，看着眼前换好衣服的璃落和流萤，公式化地夸赞道。流萤害羞地低下了头，而璃落则是深深看了小萌一眼。“咳咳，药绳已经准备好了，你们谁先体验呀。”小萌故意忽视了璃落幽怨的眼神，取出一根底色红色黄色条纹的绳子，摆出一个抖s常用的摔鞭动作。
            　　
            　　“哎哎哎，我，我再观望观望。”流萤缩了缩脖子，暗暗退了一步。“那就直接来吧。”璃落的回答选项隐约能听见双料特工穿山甲的声音。
            　　
            　　“没有问题。”小萌来到璃落身后，“请全身放松，双手背到身后。”璃落有些不明所以，懵懵懂懂地按照吩咐做了。小萌将手中的药绳对折后做了个绳圈，套在了璃落胸部上方。“居然是这样绑药绳的吗？”流萤有些惊奇。“是的哦，现在我在准备绑胸缚。介于两位美女是第一次来体验，我不会绑很复杂的姿势，如果两位喜欢，下次你们就可以体验更丰富的捆绑姿势啦。”小萌的声音充满了诱惑。“以后，以后再说嘛。”流萤想起了一天只能吃一个的橡木蛋糕卷，讪笑着回答道。小萌也不在意，依旧保持着职业微笑，俯身用右手捞起温泉水浇在璃落身上的药绳上，然后将药绳绕着璃落大臂和身体缠绕了两圈，收紧并在背后位置打结固定。
            　　
            　　“救命啊——”璃落选择的回答选项依旧不太正经。“美女不要害怕，药绳是不会对人体产生不良效果的。它通过本店独创的捆绑方式紧贴使用者的身体，使用者的挣扎行为可以带动药绳刺激捆绑着的身体穴位，从而达到活血化瘀的治疗效果，多使用还可以缓解负面情绪，使人心情舒畅，长期使用还能起到改善身材增加个人魅力的效果哦。”小萌从后面轻轻抱住璃落，声音温柔地在璃落耳旁解释道。
            　　
            　　“中国有句古话，叫，西西务者魏俊杰。嗯，我就是骏杰。”璃落的回答选项难得长了一次。见流萤和小萌不约而同地无视了自己，璃落索性闭上眼睛，一副女英雄英勇就义的模样等待小萌接下来的动作。这惹得流萤在一旁捂嘴偷笑：“不用这样啦，小萌是不会伤害你的。”小萌也轻轻摸了摸璃落的后背：“是的，请两位贵宾放心，我以店铺门口的投诉箱起誓，在服务过程中是绝对不敢伤害你们一分一毫的。”或许是听见小萌也被自己的说话方式影响，璃落嘴角浮起一丝笑意，身体也逐渐放松了下来。见璃落逐渐适应，小萌的捆绑动作继续，绳子从绳结处出发，绕回到璃落身前，在璃落胸部下方缠绕了几圈后，收紧在原绳结位置再打一个结固定。随后小萌将绳子分为两股，分别绕过璃落的肩膀后，穿过璃落胸部下方的绳子，再绕回璃落的后背绳结处收紧固定打结。紧接着小萌把绳子绕至璃落腋下，将缠绕璃落胸部上下的两股绳子缠绕收紧固定，并绕回到后背打结处打结固定。“好了，简单的胸缚绑好了。”小萌弯腰捧起温泉水浇在璃落身上的药绳上。“哇，绑得真好看。”流萤忍不住赞叹道。“哇，卡妈竟然手下留情了。”璃落的回答选项既有惊讶，也有一丝淡淡的幽怨。“美女如果有时间，可以常来本店哦，药绳能极大地改善身材呢。”小萌不会放过任何一次吸引顾客的机会。“下次一定，下次一定。”璃落毫不犹豫地选择了这个回答选项。“小萌静候两位的再次光临。”小萌的表情看不出来她有没有理解璃落的回答。
            　　
