            　　“我也想加入这个家，我绝对不会拆散这个家的。”璃落的回答选项让人不由得想起琼瑶笔下的新月格格，不过倒也适合现在流萤和小萌聊天几乎把璃落遗忘了的场景。“什么啦。璃落你快试试，我绑得有什么不舒服的地方吗？”流萤轻轻握住璃落吊在后背中间的双手。“动不了啦，我现在是一颗新生的蘑菇。”璃落依旧没有选择正常一些的回答选项。流萤没有就此停下关心：“如果有哪里不舒服就告诉我哦。”这次璃落正经了一回，摇了摇头表示一切正常。好一会儿之后，小萌调整好了药绳的位置与松紧程度：“幽默的美女，现在感觉如何呀？”“我感觉自己被绑起来了。”璃落选择了一个如说的回答选项。“额，还有呢？”小萌一时语塞。“我还感觉自己手臂动不了了。”璃落再次选择了一个如说的回答选项。“额，还有······”小萌的职业微笑僵了一下，正准备继续询问时，流萤出声打断了她两的对话：“好啦，我们还是继续吧，我相信小萌小姐的技术。”小萌眨眨眼，思索片刻后说道：“有任何不舒服的感觉就告诉我哦，我会为您不厌其烦地调整的。”说完，小萌就看见璃落摇了摇头。“好的，现在请美女来到这边的躺椅上哦，我会继续为您提供药绳服务。”小萌搀扶着璃落来到一个支撑架大约半米多高的躺椅前，小心翼翼地扶着璃落趴在躺椅上。
            　　
